   229  template <typename Type, typename OffsetType=HBUINT16, bool has_null=true>
   230  struct OffsetTo : Offset<OffsetType, has_null>
   231  {
   232    inline const Type& operator () (const void *base) const
   233    {
   234      if (unlikely (this->is_null ())) return Null(Type);
   235      return StructAtOffset<const Type> (base, *this);
   236    }
   237    inline Type& operator () (void *base) const
   238    {
   239      if (unlikely (this->is_null ())) return Crap(Type);
   240      return StructAtOffset<Type> (base, *this);
   241    }
   242
   243    inline Type& serialize (hb_serialize_context_t *c, const void *base)
   244    {
   245      return * (Type *) Offset<OffsetType>::serialize (c, base);
   246    }
   247
   248    template <typename T>
   249    inline void serialize_subset (hb_subset_context_t *c, const T &src, const void *base)
   250    {
   251      if (&src == &Null(T))
   252      {
   253        this->set (0);
   254        return;
   255      }
   256      serialize (c->serializer, base);
   257      if (!src.subset (c))
   258        this->set (0);
   259    }
   260
   261    inline bool sanitize_shallow (hb_sanitize_context_t *c, const void *base) const
   262    {
   263      TRACE_SANITIZE (this);
   264      if (unlikely (!c->check_struct (this))) return_trace (false);
   265      if (unlikely (this->is_null ())) return_trace (true);
   266      if (unlikely (!c->check_range (base, *this))) return_trace (false);
   267      return_trace (true);
   268    }
   269
   270    inline bool sanitize (hb_sanitize_context_t *c, const void *base) const
   271    {
   272      TRACE_SANITIZE (this);
   273      return_trace (sanitize_shallow (c, base) &&
   274                    (this->is_null () ||
   275                     StructAtOffset<Type> (base, *this).sanitize (c) ||
   276                     neuter (c)));
   277    }
   278    template <typename T1>
   279    inline bool sanitize (hb_sanitize_context_t *c, const void *base, T1 d1) const
   280    {
   281      TRACE_SANITIZE (this);
   282      return_trace (sanitize_shallow (c, base) &&
   283                    (this->is_null () ||
   284                     StructAtOffset<Type> (base, *this).sanitize (c, d1) ||
   285                     neuter (c)));
   286    }
   287    template <typename T1, typename T2>
   288    inline bool sanitize (hb_sanitize_context_t *c, const void *base, T1 d1, T2 d2) const
   289    {
   290      TRACE_SANITIZE (this);
   291      return_trace (sanitize_shallow (c, base) &&
   292                    (this->is_null () ||
   293                     StructAtOffset<Type> (base, *this).sanitize (c, d1, d2) ||
   294                     neuter (c)));
   295    }
   296    template <typename T1, typename T2, typename T3>
   297    inline bool sanitize (hb_sanitize_context_t *c, const void *base, T1 d1, T2 d2, T3 d3) const
   298    {
   299      TRACE_SANITIZE (this);
   300      return_trace (sanitize_shallow (c, base) &&
   301                    (this->is_null () ||
   302                     StructAtOffset<Type> (base, *this).sanitize (c, d1, d2, d3) ||
   303                     neuter (c)));
