   322   * Array Types
   323   */
   324
   325  template <typename Type>
   326  struct UnsizedArrayOf
   327  {
   328    inline const Type& operator [] (unsigned int i) const { return arrayZ[i]; }
   329    inline Type& operator [] (unsigned int i) { return arrayZ[i]; }
   330
   330
   331    inline bool sanitize (hb_sanitize_context_t *c, unsigned int count) const
   332    {
   333      TRACE_SANITIZE (this);
   334      if (unlikely (!sanitize_shallow (c, count))) return_trace (false);
   335
   336      /* Note: for structs that do not reference other structs,
   337       * we do not need to call their sanitize() as we already did
   338       * a bound check on the aggregate array size.  We just include
   339       * a small unreachable expression to make sure the structs
   340       * pointed to do have a simple sanitize(), ie. they do not
   341       * reference other structs via offsets.
   342       */
   343      (void) (false && arrayZ[0].sanitize (c));
   344
   345      return_trace (true);
   346    }
   347    inline bool sanitize (hb_sanitize_context_t *c, unsigned int count, const void *base) const
   348    {
   349      TRACE_SANITIZE (this);
   350      if (unlikely (!sanitize_shallow (c, count))) return_trace (false);
   351      for (unsigned int i = 0; i < count; i++)
   352        if (unlikely (!arrayZ[i].sanitize (c, base)))
   353          return_trace (false);
   354      return_trace (true);
   355    }
   356    template <typename T>
   357    inline bool sanitize (hb_sanitize_context_t *c, unsigned int count, const void *base, T user_data) const
   358    {
   359      TRACE_SANITIZE (this);
   360      if (unlikely (!sanitize_shallow (c, count))) return_trace (false);
   361      for (unsigned int i = 0; i < count; i++)
   362        if (unlikely (!arrayZ[i].sanitize (c, base, user_data)))
   363          return_trace (false);
   364      return_trace (true);
   365    }
   366
   367    inline bool sanitize_shallow (hb_sanitize_context_t *c, unsigned int count) const
   368    {
   369      TRACE_SANITIZE (this);
   370      return_trace (c->check_array (arrayZ, count));
   371    }
   372
   373    public:
   374    Type          arrayZ[VAR];
   375    public:
   376    DEFINE_SIZE_ARRAY (0, arrayZ);
   377  };
