   405  /* An array with a number of elements. */
   406  template <typename Type, typename LenType=HBUINT16>
   407  struct ArrayOf
   408  {
   409    const Type *sub_array (unsigned int start_offset, unsigned int *pcount /* IN/OUT */) const
   410    {
   411      unsigned int count = len;
   412      if (unlikely (start_offset > count))
   413        count = 0;
   414      else
   415        count -= start_offset;
   416      count = MIN (count, *pcount);
   417      *pcount = count;
   418      return arrayZ + start_offset;
   419    }
   420
   421    inline const Type& operator [] (unsigned int i) const
   422    {
   423      if (unlikely (i >= len)) return Null(Type);
   424      return arrayZ[i];
   425    }
